def solve():
    solutions = []
    z_max = 10

    print(f"Starting search for solutions (x, y, z) such that 1 <= x <= y <= z <= {z_max}")

    for z in range(1, z_max + 1):
        for y in range(1, z + 1):
            for x in range(1, y + 1):
                lhs = x**3 + y**3 + z**3
                rhs = x**2 * y**2 * z**2

                if lhs == rhs:
                    solutions.append((x, y, z))

    print("\n--- Results ---")
    if solutions:
        print("Found solutions:")
        for sol in solutions:
            print(sol)
    else:
        print("No solutions found in the given range.")

    # Check efficiency comment
    # The search space size is approximately n^3/6 where n=10. (10*11*12 / 6, roughly).
    # For n=10, the number of triples is small (55 triples). This is highly efficient.
    print("\nComputational Efficiency Check:")
    print("The search space size is very small (O(N^3) where N=10), making the search extremely fast and efficient.")

